package com.motionstudio.part3
import kotlin.math.*
data class Keyframe<T>(val time:Double,val value:T,val interpolation:Interpolation=Interpolation.LINEAR,val inTangent:Double=0.0,val outTangent:Double=0.0)
enum class Interpolation{HOLD,LINEAR,BEZIER,EASE_IN,EASE_OUT}
class KeyframeTrack<T>(private val interpolate:(T,T,Double)->T){private val keys=mutableListOf<Keyframe<T>>();fun add(k:Keyframe<T>){keys.removeIf{abs(it.time-k.time)<1e-9};keys.add(k);keys.sortBy{it.time}};fun remove(time:Double){keys.removeIf{abs(it.time-time)<1e-9}};fun all()=keys.toList();fun evaluate(time:Double):T?{if(keys.isEmpty())return null;if(time<=keys.first().time)return keys.first().value;if(time>=keys.last().time)return keys.last().value;val i=keys.indexOfLast{it.time<=time};val a=keys[i];val b=keys[i+1];if(a.interpolation==Interpolation.HOLD)return a.value;var u=((time-a.time)/(b.time-a.time)).coerceIn(0.0,1.0);u=when(a.interpolation){Interpolation.EASE_IN->u*u;Interpolation.EASE_OUT->1-(1-u)*(1-u);else->u};return interpolate(a.value,b.value,u)} }
object KeyframeMath{fun scalar()=KeyframeTrack<Double>{a,b,t->a+(b-a)*t};fun vector(n:Int)=KeyframeTrack<DoubleArray>{a,b,t->require(a.size==n&&b.size==n);DoubleArray(n){i->a[i]+(b[i]-a[i])*t}};fun color()=vector(4);fun bezierScalar(a:Keyframe<Double>,b:Keyframe<Double>,t:Double):Double{val u=1-t;return u*u*u*a.value+3*u*u*t*(a.value+a.outTangent)+3*u*t*t*(b.value-b.inTangent)+t*t*t*b.value}}
